using System;using System.IO;using System.Linq;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace MuEditorPhoenix {
 public sealed class RewardSpec {
  public int ItemId,Level,Durability,Additional,Excellent,Copies=1;public bool Skill,Luck,SocketItem;
  public void Validate(){if(ItemId<0||ItemId>=16384||(ItemId&8191)==8191)throw new Exception("ID de item não suportado pelo perfil MuDevs25.");if(Level<0||Level>15||Durability<0||Durability>255||Excellent<0||Excellent>63||Copies<1||Copies>50)throw new Exception("Opções da premiação fora do intervalo permitido.");ItemCodec25.AdditionalCode(Additional);}
 }
 public sealed class NewItemMarker {public string RequestId=Guid.NewGuid().ToString("N");public int ItemId;}
 public sealed class CreatedItemReceipt {public string RequestId,Destination;public int Slot,ItemId,Serial;}
 public static class ItemCodec25 {
  public static int AdditionalCode(int display){if(display<0||display>28||display%4!=0)throw new Exception("O adicional deve ser +0, +4, +8, +12, +16, +20, +24 ou +28.");return display/4;}
  public static int Id(byte[] bytes){if(bytes==null||bytes.Length!=25)throw new Exception("Registro de item inválido.");return bytes[0]+((bytes[7]&128)<<1)+((bytes[9]&240)<<5)+((bytes[9]&1)<<13);}
  public static uint Serial(byte[] bytes){return ((uint)bytes[3]<<24)|((uint)bytes[4]<<16)|((uint)bytes[5]<<8)|bytes[6];}
  public static void WriteSerial(byte[] bytes,uint serial){bytes[3]=(byte)(serial>>24);bytes[4]=(byte)(serial>>16);bytes[5]=(byte)(serial>>8);bytes[6]=(byte)serial;}
  public static byte[] Create(RewardSpec spec,uint serial){spec.Validate();int option=AdditionalCode(spec.Additional);var b=new byte[25];b[0]=(byte)spec.ItemId;b[1]=(byte)((spec.Skill?128:0)|(spec.Level<<3)|(spec.Luck?4:0)|(option&3));b[2]=(byte)spec.Durability;WriteSerial(b,serial);b[7]=(byte)(((spec.ItemId&256)>>1)|((option&4)<<4)|spec.Excellent);b[8]=0;b[9]=(byte)(((spec.ItemId&7680)>>5)|((spec.ItemId&8192)>>13));b[10]=spec.SocketItem?(byte)255:(byte)0;for(int i=11;i<=18;i++)b[i]=255;return b;}
 }
 public partial class Catalog {
  void LoadSocketTypes(string itemFile){SocketItems.Clear();string file=Path.Combine(Path.GetDirectoryName(itemFile),"Socket - Settings","SocketItemType.xml");if(!File.Exists(file))return;var doc=Guard.Xml(file);foreach(var node in doc.Descendants()){int section,type;if(int.TryParse((string)node.Attribute("Section"),out section)&&int.TryParse((string)node.Attribute("Type"),out type))SocketItems.Add(section*512+type);else if(node.Name.LocalName=="Item"&&int.TryParse((string)node.Attribute("Index"),out type)&&node.Parent!=null&&int.TryParse((string)node.Parent.Attribute("Index"),out section))SocketItems.Add(section*512+type);}}
 }
 public partial class ItemBuffer {
  public Dictionary<int,NewItemMarker> NewItems=new Dictionary<int,NewItemMarker>();
  public List<int> AddRewards(RewardSpec spec,Catalog catalog,int start,int end){spec.Validate();ItemDef item;if(!catalog.Items.TryGetValue(spec.ItemId,out item))throw new Exception("O item não existe no Item.xml carregado.");if(item.Section==16)throw new Exception("Este item pertence ao inventário Muun, não à bolsa/baú comum. Selecione o ovo ou outro item de premiação apropriado.");
   if(start<0||end>Count||start>=end)throw new Exception("Grade de destino inválida.");var next=new ItemBuffer(Data);var added=new List<int>();var occupied=new HashSet<int>();for(int slot=start;slot<end;slot++){if(Empty(slot))continue;ItemDef existing;if(!catalog.Items.TryGetValue(Id(slot),out existing))throw new Exception("A grade tem item não identificado; confira o Item.xml antes de inserir.");foreach(int cell in Cells(slot,existing,start,end))occupied.Add(cell);}
   for(int copy=0;copy<spec.Copies;copy++){int chosen=-1;List<int> footprint=null;for(int slot=start;slot<end;slot++){if(!next.Empty(slot))continue;try{var cells=Cells(slot,item,start,end);if(cells.Any(occupied.Contains))continue;chosen=slot;footprint=cells;break;}catch{}}if(chosen<0)throw new Exception("Espaço insuficiente na grade selecionada. Nenhum item desta inclusão foi adicionado.");next.Set(chosen,ItemCodec25.Create(spec,0));foreach(int cell in footprint)occupied.Add(cell);added.Add(chosen);}
   Data=next.Data;foreach(int slot in added)NewItems.Add(slot,new NewItemMarker{ItemId=spec.ItemId});return added;
  }
  public void CancelNew(int slot){if(!NewItems.ContainsKey(slot))throw new Exception("Selecione um item novo, ainda não salvo.");if(ItemCodec25.Serial(Get(slot))!=0)throw new Exception("O item já possui serial; recarregue os dados.");Set(slot,Enumerable.Repeat((byte)255,25).ToArray());NewItems.Remove(slot);}
 }
 public partial class Database {
  public Dictionary<int,NewItemMarker> InventoryNewItems=new Dictionary<int,NewItemMarker>();public List<CreatedItemReceipt> LastCreatedItems=new List<CreatedItemReceipt>();
  byte[] MaterializeRewards(SqlConnection connection,SqlTransaction transaction,byte[] draft,Dictionary<int,NewItemMarker> pending,string destination,List<CreatedItemReceipt> receipts){var result=(byte[])draft.Clone();if(pending.Count==0)return result;
   using(var check=new SqlCommand("SELECT COUNT_BIG(*) FROM dbo.GameServerInfo WITH(UPDLOCK,HOLDLOCK)",connection,transaction))if(Convert.ToInt64(check.ExecuteScalar())!=1)throw new Exception("O gerador de seriais requer exatamente um registro em GameServerInfo.");
   foreach(var pair in pending.OrderBy(p=>p.Key)){int offset=pair.Key*25;if(offset<0||offset+25>result.Length)throw new Exception("Slot de premiação inválido.");var item=result.Skip(offset).Take(25).ToArray();if(ItemCodec25.Id(item)!=pair.Value.ItemId||ItemCodec25.Serial(item)!=0)throw new Exception("Rascunho de premiação alterado de forma inconsistente. Recarregue o registro.");
    int serial;using(var cmd=new SqlCommand("dbo.WZ_GetItemSerial",connection,transaction){CommandType=CommandType.StoredProcedure,CommandTimeout=15}){object value=cmd.ExecuteScalar();if(value==null||value==DBNull.Value)throw new Exception("O banco não retornou serial para a premiação.");serial=Convert.ToInt32(value);}if(serial<=0||receipts.Any(r=>r.Serial==serial))throw new Exception("O gerador do servidor retornou serial inválido ou repetido.");
    using(var check=new SqlCommand("SELECT @@TRANCOUNT",connection,transaction))if(Convert.ToInt32(check.ExecuteScalar())!=1)throw new Exception("Procedimento de serial incompatível com a transação do editor.");
    ItemCodec25.WriteSerial(item,(uint)serial);Buffer.BlockCopy(item,0,result,offset,25);receipts.Add(new CreatedItemReceipt{RequestId=pair.Value.RequestId,Destination=destination,Slot=pair.Key,ItemId=pair.Value.ItemId,Serial=serial});
   }return result;
  }
 }
 public partial class PhoenixEditorForm {
  RewardSpec AskReward(ItemDef item){using(var dialog=new Form{Text="MU Editor Phoenix — "+T("Criar premiação"),Size=new Size(520,620),MinimumSize=new Size(520,620),StartPosition=FormStartPosition.CenterParent,BackColor=BackColor,ForeColor=ForeColor,Font=Font}){var body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20),AutoScroll=true};dialog.Controls.Add(body);body.Controls.Add(new Label{Text=item.Name+"\r\n"+item.Section+":"+item.Index,AutoSize=true,MaximumSize=new Size(450,0)});body.Controls.Add(new PictureBox{Image=imageBank.Get(item.Id),SizeMode=PictureBoxSizeMode.Zoom,Size=new Size(450,115),BackColor=Color.FromArgb(22,33,46)});
   var level=Number(15);var durability=Number(255);var additional=Number(28);additional.Increment=4;var excellent=Number(63);var copies=Number(50);copies.Minimum=1;copies.Value=1;int dur=0,magic=0,overlap=0;string value;if(item.Attributes.TryGetValue("Durability",out value))int.TryParse(value,out dur);if(item.Attributes.TryGetValue("MagicDurability",out value))int.TryParse(value,out magic);if(item.Attributes.TryGetValue("ItemOverlap",out value))int.TryParse(value,out overlap);durability.Value=Math.Min(255,overlap>0?1:Math.Max(dur,magic));
   foreach(var pair in new[]{new KeyValuePair<string,NumericUpDown>("Nível",level),new KeyValuePair<string,NumericUpDown>("Durabilidade",durability),new KeyValuePair<string,NumericUpDown>("Adicional",additional),new KeyValuePair<string,NumericUpDown>("Excellent",excellent),new KeyValuePair<string,NumericUpDown>("Cópias",copies)}){var line=new FlowLayoutPanel{Width=450,Height=34};line.Controls.Add(new Label{Text=T(pair.Key),Width=230,Padding=new Padding(0,5,0,0)});pair.Value.Width=110;line.Controls.Add(pair.Value);body.Controls.Add(line);}var skill=new CheckBox{Text="Skill",AutoSize=true};var luck=new CheckBox{Text="Luck",AutoSize=true};body.Controls.Add(skill);body.Controls.Add(luck);body.Controls.Add(new Label{Text=T("Prêmio permanente. A conta deve estar offline para salvar."),AutoSize=true,MaximumSize=new Size(450,0)});RewardSpec result=null;body.Controls.Add(Button("Adicionar",()=>{var spec=new RewardSpec{ItemId=item.Id,Level=(int)level.Value,Durability=(int)durability.Value,Additional=(int)additional.Value,Excellent=(int)excellent.Value,Skill=skill.Checked,Luck=luck.Checked,Copies=(int)copies.Value,SocketItem=catalog.SocketItems.Contains(item.Id)};spec.Validate();result=spec;dialog.DialogResult=DialogResult.OK;}));return dialog.ShowDialog(this)==DialogResult.OK?result:null;}}
  void AddReward(bool toWarehouse){ItemBoard board=toWarehouse?warehouseBoard:inventoryBoard;if(board.Buffer==null)throw new Exception(toWarehouse?"Selecione a conta e abra o baú.":"Selecione um personagem na lista.");if(!toWarehouse&&inventoryRegion.SelectedIndex==1){inventoryRegion.SelectedIndex=0;RefreshBoards();}if(!toWarehouse)CheckInventoryArea(board,board.Start);ItemDef item=PickItem();if(item==null)return;var spec=AskReward(item);if(spec==null)return;var slots=board.Buffer.AddRewards(spec,catalog,board.Start,board.End);board.Selected=slots[0];board.Invalidate();SelectStorageItem(board,slots[0]);storageLabel.Text=T("Premiação preparada. Clique em Salvar para entregar.");}
  void CancelNewReward(){if(currentBoard==null||currentItem<0)throw new Exception("Selecione um item novo na grade.");currentBoard.Buffer.CancelNew(currentItem);if((inventoryDraft==null||!inventoryDraft.Dirty)&&(db.Warehouse==null||!db.Warehouse.Dirty))db.CrossStorageDirty=false;currentBoard.Invalidate();SelectStorageItem(currentBoard,currentItem);storageLabel.Text=T("Alterações pendentes");}
 }
}
